steps.solve:
cd $R/layout
cat > terraform.tf <<'HCL'
terraform {
  required_providers {
    local = { source = "hashicorp/local" }
  }
}
HCL
cat > main.tf <<'HCL'
resource "local_file" "crew" {
  filename = "${path.module}/crew.txt"
  content  = "Crew of the shipyard"
}
HCL
cat > outputs.tf <<'HCL'
output "crew_file" {
  value = local_file.crew.filename
}
HCL
rm all.tf
terraform fmt
terraform init
terraform validate

cd $R/harbors
cat >> main.tf <<'HCL'

provider "local" {
  alias = "backup"
}

resource "local_file" "backup" {
  provider = local.backup
  filename = "${path.module}/backup.txt"
  content  = "backup records"
}
HCL
terraform apply -auto-approve

cd $R/supplier
terraform init || true
cat > versions.tf <<'HCL'
terraform {
  required_providers {
    docker = {
      source = "kreuzwerker/docker"
    }
  }
}
HCL
terraform init
terraform validate

