steps.solve:
cd $R/inspect
cat > variables.tf <<'HCL'
variable "env" {
  type    = string
  default = "dev"

  validation {
    condition     = contains(["dev", "prod"], var.env)
    error_message = "env must be dev or prod."
  }
}

variable "masts" {
  type    = number
  default = 2

  validation {
    condition     = var.masts >= 1 && var.masts <= 5
    error_message = "A ship has 1 to 5 masts."
  }
}

variable "crew" {
  type    = list(string)
  default = ["Ada", "Bo"]
}
HCL
terraform plan -var env=staging || true

