steps.solve:
cd $R/inspect
sed -i 's|  content  = "${var.env}: ${var.masts} masts, ${length(var.crew)} crew"|&

  lifecycle {
    precondition {
      condition     = length(var.crew) >= var.masts
      error_message = "Each mast needs at least one crew member."
    }
  }|' main.tf
terraform plan -var masts=3 || true

cd $R/lookout
cat >> main.tf <<'HCL'

